mapper.select:
select  from pm_project_initiation_attachment
where approval_id = #{approvalId}
and section_code = #{sectionCode}
order by upload_time, attachment_id

mapper.update:
update pm_project_initiation_attachment
set approval_id = #{approvalId}, version_no = #{versionNo}
where project_id = #{projectId} and approval_id is null
